<?php require __DIR__ . '/../config/bootstrap.php'; if(!empty($_SESSION['member_id'])){header('Location:/member/index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('SELECT id,password_hash FROM members WHERE email=? AND status<>"archived" LIMIT 1');$s->execute([trim($_POST['email']??'')]);$m=$s->fetch();if($m&&password_verify($_POST['password']??'',$m['password_hash'])){session_regenerate_id(true);unset($_SESSION['admin_id'],$_SESSION['admin_name'],$_SESSION['admin_role']);$_SESSION['member_id']=$m['id'];header('Location:/member/index.php');exit;}$error='ईमेल किंवा पासवर्ड चुकीचा आहे.';} ?>
